blocks.code:
SELECT empleado_id, vendido * 100.0 / meta AS cumplimiento FROM metas;
SELECT empleado_id, meta, vendido,
       round(vendido * 100.0 / NULLIF(meta, 0), 1)                              AS cumplimiento,
       COALESCE(round(vendido * 100.0 / NULLIF(meta, 0), 1) || ' %', 'sin meta') AS informe
FROM metas
ORDER BY empleado_id;

