blocks.code:
SELECT regexp_split_to_table(titulo, '\s+') AS palabra
FROM libros
WHERE id = 3;
SELECT titulo,
       regexp_count(titulo, '\S+')                 AS palabras,
       regexp_split_to_array(lower(titulo), '\s+') AS arreglo
FROM libros
WHERE genero = 'Poesía'
ORDER BY palabras DESC, titulo;
SELECT regexp_matches('Rayuela 1963, 736 páginas, 2 ejemplares', '\d+', 'g') AS numeros;

